            if best is None or schedule < best:
                best = schedule
    if best is not None:
        break


def quote(s):
    if '"' in s and "'" not in s:
        return "'" + s + "'"
    if "'" in s and '"' not in s:
        return '"' + s + '"'
    return '"' + s.replace("\\", "\\\\").replace('"', '\\"') + '"'


if best is None:
    print("[]")
else:
    print("[" + ", ".join(quote(s) for s in best[1]) + "]")
